 const feedEntry=legend?.querySelector('[data-legend="feed"]');
 if(planeEntry)planeEntry.hidden=!plane;
 const hasSection=plane&&radiation&&Boolean(el("farfield").data?.some(t=>t.name==="Continuous plane intersection"));
