  ctx.beginPath();ctx.arc(x,y,11.5,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle=EXPORT_AXIS_COLORS[p.axis];ctx.lineWidth=1.2;ctx.stroke();
  ctx.fillStyle=EXPORT_AXIS_COLORS[p.axis];
