async function saveSceneImage(){
 const graph=el("farfield"),button=el("saveImage");
 if(!graph?._fullLayout||!field)return;
 button.disabled=true;button.setAttribute("aria-busy","true");
 try{
  const width=Math.round(graph.clientWidth),height=Math.round(graph.clientHeight);
  if(width<100||height<100)throw Error("The 3D view is too small to export");
  // High resolution but bounded to protect mobile GPU memory.
  const factor=Math.min(6,3000/Math.max(width,height),Math.sqrt(9000000/(width*height)));
  const outWidth=Math.round(width*factor),outHeight=Math.round(height*factor);
  const camera=captureCamera();
  // Synchronize Plotly's camera state with the live WebGL view.
  await Plotly.relayout(graph,{"scene.camera":camera});
  const png=await Plotly.toImage(graph,{format:"png",width:outWidth,height:outHeight,scale:1});
  const source=new Image();
  const loaded=new Promise((resolve,reject)=>{
   source.onload=resolve;source.onerror=()=>reject(Error("Plot image encoding failed"));
  });
  source.src=png;await loaded;
  const canvas=document.createElement("canvas");
  canvas.width=outWidth;canvas.height=outHeight;
  const ctx=canvas.getContext("2d");
  if(!ctx)throw Error("Canvas export is unavailable");
  ctx.drawImage(source,0,0,outWidth,outHeight);
  ctx.setTransform(outWidth/width,0,0,outHeight/height,0,0);
  exportSceneOverlays(ctx,width,height,camera);
  const blob=await new Promise((resolve,reject)=>{
   canvas.toBlob(result=>result?resolve(result):reject(Error("PNG encoding failed")),"image/png");
  });
  const filename=(active?.name||"antenna").replace(/[^a-zA-Z0-9_-]+/g,"-").slice(0,55);
  const freq=Number(field.frequency_hz/1e9).toFixed(3);
  const url=URL.createObjectURL(blob);
  const link=document.createElement("a");
  link.href=url;link.download="radiators-"+filename+"-"+freq+"GHz.png";
  document.body.append(link);link.click();link.remove();
  setTimeout(()=>URL.revokeObjectURL(url),30000);
 }catch(error){
  console.error("Save high-resolution image failed",error);
  status("Save image failed: "+error.message);
 }finally{
  button.disabled=false;button.removeAttribute("aria-busy");
 }
}
function formatPoseNumber(value){
 // Explicit ASCII + / - and two decimal places, including on mobile.
 return (value>=0?"+":"")+value.toFixed(2);
}
function readPoseNumber(value){
 const text=String(value).trim().replace(/\u2212/g,"-");
 if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(text))return null;
 const num=Number(text);
 return Number.isFinite(num)&&Math.abs(num)<=1000000?num:null;
}
// Uniformly spaced detents map to ±1, ±2, ±4, ±8 in world units.
function logarithmicJogOffset(detent){
 const n=Math.max(-4,Math.min(4,Math.round(detent)));
 return n===0?0:Math.sign(n)*Math.pow(2,Math.abs(n)-1);
}
function resetIncrementalSlider(id){
 sliderOffsets[id]=0;
 const slider=el(id+"Slider");
 slider.value="0";
 slider.setAttribute("aria-valuetext","0 "+(["px","py","pz"].includes(id)?"mm":"°"));
}
function resetIncrementalSliders(){
 for(const id of POSE_AXIS_IDS)resetIncrementalSlider(id);
}
function applyIncrementalSlider(id,detent){
 if(!Number.isFinite(detent))return;
 const offset=logarithmicJogOffset(detent);
 const delta=offset-sliderOffsets[id];
 sliderOffsets[id]=offset;
 const slider=el(id+"Slider");
 const unit=["px","py","pz"].includes(id)?"mm":"°";
 slider.setAttribute("aria-valuetext",(offset>=0?"+":"")+offset+" "+unit);
 if(delta!==0){
  setPoseAxis(id,lastValidPose[id]+delta);
  if(!["px","py","pz"].includes(id))updatePresetButtons();
  scheduleSceneRender();
 }
}
function setPoseAxis(id,value){
 if(!Number.isFinite(value)||Math.abs(value)>1000000)return;
 lastValidPose[id]=value;
 const input=el(id);
 input.value=formatPoseNumber(value);
 input.removeAttribute("aria-invalid");
}
function updatePresetButtons(){
 const values=["roll","pitch","yaw"].map(id=>readPoseNumber(el(id).value));
 for(const button of document.querySelectorAll("[data-plane]")){
  const preset=POSE_PRESETS[button.dataset.plane];
  const selected=preset&&values.every((v,i)=>v!==null&&Math.abs(v-preset[i])<.001);
  button.classList.toggle("active",Boolean(selected));
  button.setAttribute("aria-pressed",String(Boolean(selected)));
 }
}
async function renderS11(result=active){
 const s=result.s11,x=s.frequency_hz.map(f=>f/1e9);
 await Plotly.react("s11Plot",[
  {x,y:s.logmag_db,type:"scatter",mode:"lines",name:"|S11| dB",line:{color:"#61dce5",width:2}},
  {x,y:s.phase_deg,type:"scatter",mode:"lines",name:"Phase °",yaxis:"y2",line:{color:"#ffba79",width:2}}
 ],{...PALETTE,margin:{l:53,r:49,t:27,b:35},
  legend:{orientation:"h",x:0,y:1.23,font:{size:10}},
  xaxis:{title:"Frequency (GHz)",gridcolor:"#263e57"},
  yaxis:{title:"dB",gridcolor:"#263e57",titlefont:{color:"#61dce5"}},
  yaxis2:{title:"°",side:"right",overlaying:"y",range:[-180,180],titlefont:{color:"#ffba79"}}},PLOT_CFG);
 await Plotly.react("vswrPlot",[{x,y:s.vswr,type:"scatter",mode:"lines",
  line:{color:"#60d7bc",width:2},hovertemplate:"%{x:.4f} GHz: %{y:.2f}<extra></extra>"}],
 {...PALETTE,margin:{l:53,r:14,t:10,b:32},
  xaxis:{title:"Frequency (GHz)",gridcolor:"#263e57"},
  yaxis:{title:"VSWR",gridcolor:"#263e57",rangemode:"tozero",autorange:true}},PLOT_CFG);
}
async function renderPattern(){
 const token=++selectedPatternVersion;
 const runPath=el("case").value,run=active;
 try{
  if(!run||!run.patterns?.length)throw Error("No simulation is selected");
  const index=Number(el("freq").value);
  const pattern=run.patterns[index];
  if(!pattern)throw Error("Unknown frequency index "+index);
  status("Loading "+format(pattern.frequency_hz/1e9,3)+" GHz pattern…");
  const base=runPath.replace(/result\.json$/,"");
  const result=await getJSON(base+pattern.file);
  if(token!==selectedPatternVersion||runPath!==el("case").value)return;
  if(!Array.isArray(result.directivity_dbi)||!result.directivity_dbi.length)
   throw Error("Pattern has no directivity grid: "+pattern.file);
  field=result;
  cachedField=null;
  el("peak").textContent="Peak D "+format(result.max_directivity_dbi)+" dBi";
  updateCenterStats(sceneCamera||DEFAULT_CAMERA);
  status("Rendering "+format(result.frequency_hz/1e9,3)+" GHz…");
  await renderScene();
  if(token!==selectedPatternVersion||runPath!==el("case").value)return;
  status("Ready · "+format(result.frequency_hz/1e9,3)+" GHz");
 }catch(error){
  if(token===selectedPatternVersion){
   status("Pattern load failed: "+error.message);
   console.error("Pattern load failed",error);
  }
 }
}
async function renderRun(){
 const token=++selectedRunVersion;
 ++selectedPatternVersion;
 const path=el("case").value;
 el("freq").disabled=true;
 try{
  status("Loading simulation "+path.split("/").slice(-2,-1)[0]+"…");
  const result=await getJSON(path);
  if(token!==selectedRunVersion||el("case").value!==path)return;
  if(!Array.isArray(result.patterns)||!result.patterns.length)
   throw Error("Simulation has no frequency patterns");
  active=result;field=null;
  sceneCamera=null;orbitCenter={...DEFAULT_CAMERA.center};zoomEye=null;activePanAxis=null;cachedField=null;
  updatePanStatus();updateAxisGizmo(DEFAULT_CAMERA);resetIncrementalSliders();
  el("mesh").textContent=Number(active.mesh_total_cells).toLocaleString()+" cells";
  el("config").textContent=JSON.stringify(active.input_config,null,2);
  el("freq").replaceChildren(...active.patterns.map((p,index)=>{
   const option=document.createElement("option");
   option.value=index;
   option.textContent=format(p.frequency_hz/1e9,3)+" GHz";
   return option;
  }));
  // Keep the selected frequency, when possible, across antennas.
  const preferred=active.patterns.findIndex(p=>p.frequency_hz===2450000000);
  el("freq").value=String(preferred<0?0:preferred);
  el("freq").disabled=false;
  status("Rendering S11 for "+active.name+"…");
  await renderS11(result);
  if(token!==selectedRunVersion||el("case").value!==path)return;
  await renderPattern();
 }catch(error){
  if(token===selectedRunVersion){
   el("freq").disabled=false;
   status("Simulation load failed: "+error.message);
   console.error("Simulation load failed",error);
  }
 }
}
// The two selectors have distinct levels: Simulation -> only its own Cases.
// For non-sweeps, Case remains visible with a single "Default" entry.
function selectSimulation(){
 const cases=RadiatorsSelectors.casesForSimulation(simulations,el("simulation").value);
 el("case").replaceChildren(...cases.map(item=>{
  const option=document.createElement("option");
  option.value=item.path;
  option.textContent=item.name||item.id;
  return option;
 }));
 el("case").disabled=!cases.length;
 if(!cases.length){
  status("No cases for the selected simulation");
  return;
 }
 el("case").value=cases[0].path;
 renderRun();
}

function setMode(next){
 mode=next;document.body.dataset.mode=next;
 for(const button of document.querySelectorAll(".view-tabs button")){
  button.classList.toggle("active",button.dataset.mode===next);
 }
 el("showGeometry").checked=next!=="radiation";
 el("showRadiation").checked=next!=="geometry";
 el("showPlane").checked=next==="combined";
 updateSceneLegend();
 scheduleSceneRender();
 setTimeoutResize();
}
function setTimeoutResize(){
 requestAnimationFrame(async()=>{
  for(const id of ["farfield","s11Plot","vswrPlot"]){
   const graph=el(id);
   if(graph?._fullLayout)await Plotly.Plots.resize(graph);
  }
  alignViewCenter();
 });
}
(function setupControls(){
 el("resetView").addEventListener("click",resetCamera);
 el("saveImage").addEventListener("click",saveSceneImage);
 el("zoomIn").addEventListener("click",()=>zoomCamera(.8));
 el("zoomOut").addEventListener("click",()=>zoomCamera(1.25));
 // Required: selecting a different antenna or frequency must reload its data.
 el("simulation").addEventListener("change",selectSimulation);
 el("case").addEventListener("change",renderRun);
 el("freq").addEventListener("change",renderPattern);
 setupAxisPan();
 // WebGL updates its live camera throughout pointer drags, but Plotly's
 // relayout event may be deferred until mouseup. Keep the axis triad live.
 const graph=el("farfield");
 // Plotly's colorbar and scene dimensions can change after a resize.
 window.addEventListener("resize",()=>{
  requestAnimationFrame(()=>alignViewCenter());
 },{passive:true});
 if(typeof ResizeObserver!=="undefined"){
  new ResizeObserver(()=>requestAnimationFrame(alignViewCenter))
   .observe(el("sceneStage"));
 }
 graph.addEventListener("pointerdown",()=>{zoomEye=null;},{passive:true});
 let gizmoFramePending=false;
 const refreshGizmo=()=>{
  if(gizmoFramePending)return;
  gizmoFramePending=true;
  requestAnimationFrame(()=>{
   gizmoFramePending=false;
   if(graph._fullLayout&&!zoomEye)updateAxisGizmo(captureCamera());
  });
 };
 for(const eventName of ["pointermove","mousemove","pointerup","mouseup"])
  graph.addEventListener(eventName,refreshGizmo,{passive:true});
 graph.addEventListener("wheel",event=>{
  event.preventDefault();
  const pixels=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?graph.clientHeight:1);
  const factor=Math.exp(Math.max(-250,Math.min(250,pixels))*.0012);
  zoomCamera(factor).catch(error=>{status("Zoom error: "+error.message);console.error(error)});
 },{passive:false});
 for(const button of document.querySelectorAll(".view-tabs button")){
  button.addEventListener("click",()=>setMode(button.dataset.mode));
 }
 for(const id of ["showGeometry","showRadiation","showPlane"])
  el(id).addEventListener("change",()=>{updateSceneLegend();scheduleSceneRender()});

 for(const id of POSE_AXIS_IDS){
  const input=el(id),slider=el(id+"Slider");
  slider.addEventListener("input",()=>applyIncrementalSlider(id,Number(slider.value)));
  // Re-center after pointer, touch, keyboard or assistive input ends.
  for(const eventName of ["pointerup","pointercancel","touchend","touchcancel","keyup","change","blur"]){
   slider.addEventListener(eventName,()=>resetIncrementalSlider(id));
  }
  input.addEventListener("input",()=>{
   const number=readPoseNumber(input.value);
   if(number===null){
    input.setAttribute("aria-invalid","true");
    return; // Allow a partial input such as "-" while typing.
   }
   lastValidPose[id]=number;
   input.removeAttribute("aria-invalid");
   resetIncrementalSlider(id);
   if(!["px","py","pz"].includes(id))updatePresetButtons();
   scheduleSceneRender();
  });
  input.addEventListener("blur",()=>{
   const value=readPoseNumber(input.value);
   setPoseAxis(id,value===null?lastValidPose[id]:value);
   resetIncrementalSlider(id);
   if(!["px","py","pz"].includes(id))updatePresetButtons();
   scheduleSceneRender();
  });
  input.addEventListener("keydown",event=>{
   if(event.key==="Enter"){event.preventDefault();input.blur();}
   if(event.key==="Escape"){
    input.value=formatPoseNumber(lastValidPose[id]);input.blur();
   }
  });
 }
 el("poseReset").addEventListener("click",()=>{
  for(const id of POSE_AXIS_IDS)setPoseAxis(id,0);
  resetIncrementalSliders();
  el("showPlane").checked=true;
  updatePresetButtons();
  scheduleSceneRender();
 });
 for(const preset of document.querySelectorAll("[data-plane]")){
  preset.addEventListener("click",()=>{
   const angles=POSE_PRESETS[preset.dataset.plane];
   if(!angles)return;
   ["roll","pitch","yaw"].forEach((id,index)=>setPoseAxis(id,angles[index]));
   ["roll","pitch","yaw"].forEach(resetIncrementalSlider);
   el("showPlane").checked=true;
   updatePresetButtons();
   scheduleSceneRender();
  });
 }
 updatePresetButtons();
})();
(async function init(){
 try{
  if(!window.Plotly)throw Error("Plotly library is unavailable");
  const manifest=await getJSON("./manifest.json");
  simulations=RadiatorsSelectors.readSimulations(manifest);
  // The legacy flattened manifest.runs is intentionally not a selector source.
  runs=manifest.runs||[];
  if(!simulations.length){status("No published results yet");return}
  el("simulation").replaceChildren(...simulations.map(item=>{
   const option=document.createElement("option");
   option.value=item.id;
   option.textContent=item.name;
   return option;
  }));
  selectSimulation();
 }catch(error){status("Viewer error: "+error.message);console.error(error)}
})();
